+/// @brief Spend 1.5s standing
+/// @param cmd Issue control command
+/// @param time Current timestamp
+/// @param data_state Real-time status data of robot
+void TestExample::Motion(RobotCmd &cmd, double time,RobotData &data_state) {
+  double motion_time = 1.5;
+  double cycle_time = 0.001;
+  goal_angle_fl << cmd.fl_leg[0].position, cmd.fl_leg[1].position, cmd.fl_leg[2].position;
+  goal_angle_fr << cmd.fr_leg[0].position, cmd.fr_leg[1].position, cmd.fr_leg[2].position;
+  goal_angle_hl << cmd.hl_leg[0].position, cmd.hl_leg[1].position, cmd.hl_leg[2].position;
+  goal_angle_hr << cmd.hr_leg[0].position, cmd.hr_leg[1].position, cmd.hr_leg[2].position;
+
+  if (time <= init_time + motion_time) {
+    SwingToAngle(init_angle_fl, goal_angle_fl, motion_time, time - init_time,
+                 cycle_time, "FL", cmd, data_state);
+    SwingToAngle(init_angle_fr, goal_angle_fr, motion_time, time - init_time,
+                 cycle_time, "FR", cmd,data_state);
+    SwingToAngle(init_angle_hl, goal_angle_hl, motion_time, time - init_time,
+                 cycle_time, "HL", cmd,data_state);
+    SwingToAngle(init_angle_hr, goal_angle_hr, motion_time, time - init_time,
+                 cycle_time, "HR", cmd,data_state);
+  }else{
+    for (int i = 0; i < 12; i++) {
+      cmd.joint_cmd[i].torque = 0;
+      cmd.joint_cmd[i].kp = 45;
+      cmd.joint_cmd[i].kd = 0.7;
+    }
+
+    // FL
+    cmd.joint_cmd[3*0].position = cmd.fl_leg[0].position;
+    cmd.joint_cmd[3*0+1].position = cmd.fl_leg[1].position;
+    cmd.joint_cmd[3*0+2].position = cmd.fl_leg[2].position;
+    cmd.joint_cmd[3*0].velocity = 0;
+    cmd.joint_cmd[3*0+1].velocity = 0;
+    cmd.joint_cmd[3*0+2].velocity = 0;
+
+    // FR
+    cmd.joint_cmd[3*1].position = cmd.fr_leg[0].position;
+    cmd.joint_cmd[3*1+1].position = cmd.fr_leg[1].position;
+    cmd.joint_cmd[3*1+2].position = cmd.fr_leg[2].position;
+    cmd.joint_cmd[3*1].velocity = 0;
+    cmd.joint_cmd[3*1+1].velocity = 0;
+    cmd.joint_cmd[3*1+2].velocity = 0;
+
+    // HL
+    cmd.joint_cmd[3*2].position = cmd.hl_leg[0].position;
+    cmd.joint_cmd[3*2+1].position = cmd.hl_leg[1].position;
+    cmd.joint_cmd[3*2+2].position = cmd.hl_leg[2].position;
+    cmd.joint_cmd[3*2].velocity = 0;
+    cmd.joint_cmd[3*2+1].velocity = 0;
+    cmd.joint_cmd[3*2+2].velocity = 0;
+
+    // HR
+    cmd.joint_cmd[3*3].position = cmd.hr_leg[0].position;
+    cmd.joint_cmd[3*3+1].position = cmd.hr_leg[1].position;
+    cmd.joint_cmd[3*3+2].position = cmd.hr_leg[2].position;
+    cmd.joint_cmd[3*3].velocity = 0;
+    cmd.joint_cmd[3*3+1].velocity = 0;
+    cmd.joint_cmd[3*3+2].velocity = 0;
+  }
+}
